    const labels = [
      ...host!.querySelectorAll(".hs-properties__editlabel"),
    ].map((el) => el.textContent);
    expect(labels).toEqual(["音高", "音の長さ", "開始位置", "操作"]);

    act(() => editButton("＋半音").click());
